import sys
from datetime import datetime, timedelta


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def hm(total):
    return f"{total // 60}:{total % 60:02d}"


def iso_week(d):
    """Get the ISO week number from a date string."""
    d = datetime.strptime(d, "%Y-%m-%d")
    return d.strftime("%Y-W%W")


def main():
    target = {}
    weeks = {}
    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        if parts[0] == "target":
            target[parts[1]] = minutes(parts[2])
            continue
        name, day, start, end = parts
        week = iso_week(day)
        key = (name, week)
        start_time = datetime.strptime(start, "%H:%M").time()
        end_time = datetime.strptime(end, "%H:%M").time()
        if end_time < start_time:
            end_time += timedelta(days=1)
        duration = (datetime.combine(datetime.strptime(day, "%Y-%m-%d"), end_time) -
                   datetime.combine(datetime.strptime(day, "%Y-%m-%d"), start_time)).total_seconds() / 60
        weeks[key] = weeks.get(key, 0) + duration
    balance = {}
    for name, week in sorted(weeks):
        target_hours = target.get(name, 40 * 60)
        worked = weeks[(name, week)]
        diff = worked - target_hours
        balance[name] = balance.get(name, 0) + diff
        sign = "+" if diff >= 0 else "-"
        print(f"{name} {week} {hm(worked)} {sign}{hm(abs(diff))}")
    for name in sorted(balance):
        print(f"{name} overtime {hm(max(balance[name], 0))}")


if __name__ == "__main__":
    main()
